/* =====================================================================
   Kalinaw Retail Group - RetailOps sample database
   Training Program: Phase 1, Exercise 1
   Target: Microsoft SQL Server 2019+ (also works on 2017 / Azure SQL Edge)
   Run in SSMS or Azure Data Studio. Re-runnable: drops and recreates DB.
   ===================================================================== */
USE master;
GO
IF DB_ID(N'RetailOps') IS NOT NULL
BEGIN
    ALTER DATABASE RetailOps SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE RetailOps;
END
GO
CREATE DATABASE RetailOps;
GO
USE RetailOps;
GO
CREATE TABLE dbo.Stores (
    StoreID      INT IDENTITY(1,1) PRIMARY KEY,
    StoreCode    VARCHAR(10)   NOT NULL UNIQUE,
    StoreName    NVARCHAR(100) NOT NULL,
    Region       NVARCHAR(50)  NULL,
    City         NVARCHAR(50)  NULL,
    OpenDate     DATE          NULL,
    IsActive     BIT           NOT NULL DEFAULT 1
);
CREATE TABLE dbo.Products (
    ProductID    INT IDENTITY(1,1) PRIMARY KEY,
    SKU          VARCHAR(20)   NOT NULL UNIQUE,
    ProductName  NVARCHAR(150) NOT NULL,
    Category     NVARCHAR(50)  NOT NULL,
    Brand        NVARCHAR(50)  NULL,
    UnitCost     DECIMAL(10,2) NULL,
    ListPrice    DECIMAL(10,2) NOT NULL,
    IsActive     BIT           NOT NULL DEFAULT 1
);
CREATE TABLE dbo.Customers (
    CustomerID   INT IDENTITY(1,1) PRIMARY KEY,
    FirstName    NVARCHAR(50)  NOT NULL,
    LastName     NVARCHAR(50)  NOT NULL,
    Email        NVARCHAR(120) NULL,
    City         NVARCHAR(50)  NULL,
    LoyaltyTier  VARCHAR(10)   NULL,
    CreatedAt    DATETIME2(0)  NOT NULL
);
CREATE TABLE dbo.SalesOrders (
    OrderID       INT IDENTITY(1,1) PRIMARY KEY,
    OrderNumber   VARCHAR(20)  NOT NULL UNIQUE,
    StoreID       INT          NOT NULL REFERENCES dbo.Stores(StoreID),
    CustomerID    INT          NULL REFERENCES dbo.Customers(CustomerID),  -- NULL = walk-in
    OrderDate     DATETIME2(0) NOT NULL,
    Status        VARCHAR(20)  NOT NULL,
    PaymentMethod VARCHAR(20)  NULL
);
CREATE TABLE dbo.SalesOrderLines (
    OrderLineID  INT IDENTITY(1,1) PRIMARY KEY,
    OrderID      INT           NOT NULL REFERENCES dbo.SalesOrders(OrderID),
    ProductID    INT           NOT NULL REFERENCES dbo.Products(ProductID),
    Quantity     INT           NOT NULL,
    UnitPrice    DECIMAL(10,2) NULL,
    DiscountPct  DECIMAL(5,2)  NOT NULL DEFAULT 0,
    LoadBatchID  INT           NOT NULL,
    LoadedAt     DATETIME2(0)  NOT NULL
);
CREATE TABLE dbo.Inventory (
    InventoryID   INT IDENTITY(1,1) PRIMARY KEY,
    StoreID       INT          NOT NULL REFERENCES dbo.Stores(StoreID),
    ProductID     INT          NOT NULL REFERENCES dbo.Products(ProductID),
    QtyOnHand     INT          NOT NULL,
    ReorderPoint  INT          NOT NULL,
    SnapshotDate  DATE         NOT NULL
);
GO

SET IDENTITY_INSERT dbo.Stores ON;
